files.schedule.mjs:
// Frozen eight-pair schedule for the 0.14.0 productivity screen.
//
// Pairs are executed in the declared order; within each pair the arm order
// alternates AB/BA. Both slots of a pair are adjacent, so a pair completes
// before the next. The order is execution order, not a preferred outcome.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");

const CAMPAIGN = "pd-20261111";
const PAIRS = [
    { scenario: "R01", order: ["A", "B"] },
    { scenario: "S02", order: ["B", "A"] },
    { scenario: "R02", order: ["A", "B"] },
    { scenario: "R03", order: ["B", "A"] },
    { scenario: "S05", order: ["A", "B"] },
    { scenario: "S06", order: ["B", "A"] },
    { scenario: "S07", order: ["A", "B"] },
    { scenario: "R04", order: ["B", "A"] },
];

const slots = [];
let slot = 1;
for (const [index, pair] of PAIRS.entries()) {
    const pairId = `P${String(index + 1).padStart(2, "0")}`;
    for (const arm of pair.order) {
        slots.push({
            slot,
            pairId,
            repetition: 0,
            scenario: pair.scenario,
            arm,
            stamp: `pd-${arm}-r0-${pair.scenario}`,
        });
        slot += 1;
    }
}

const problems = [];
if (slots.length !== 16) problems.push(`expected 16 slots, found ${slots.length}`);
for (let index = 0; index < slots.length; index += 2) {
    const [first, second] = [slots[index], slots[index + 1]];
    if (!first || !second) {
        problems.push(`unpaired slot at index ${index}`);
        continue;
    }
    if (first.pairId !== second.pairId)
        problems.push(`pair split at ${first.slot}/${second.slot}`);
    if (first.arm === second.arm)
        problems.push(`pair ${first.pairId} repeats arm ${first.arm}`);
    if (first.scenario !== second.scenario)
        problems.push(`pair ${first.pairId} mixes scenarios`);
    const expected = PAIRS[Number(first.pairId.slice(1)) - 1].order;
    if (first.arm !== expected[0] || second.arm !== expected[1])
        problems.push(
            `pair ${first.pairId} order ${first.arm}/${second.arm}, expected ${expected.join("/")}`,
        );
}
for (const arm of ["A", "B"]) {
    const armSlots = slots.filter((one) => one.arm === arm);
    if (armSlots.length !== 8)
        problems.push(`arm ${arm} has ${armSlots.length} slots`);
}
const stamps = new Set(slots.map((one) => one.stamp));
if (stamps.size !== slots.length) problems.push("duplicate stamp");
if (problems.length > 0) {
    console.error(problems.join("\n"));
    process.exit(1);
}

const schedule = {
    campaign: CAMPAIGN,
    generator: "declared pair order; AB/BA alternating; adjacent pair slots",
    slots,
};
writeFileSync(
    `${ROOT}/evidence/schedule.json`,
    `${JSON.stringify(schedule, null, 2)}\n`,
);
console.log(
    `wrote ${slots.length} slots, 8 pairs, sha256 ${createHash("sha256")
        .update(JSON.stringify(slots), "utf8")
        .digest("hex")}`,
);

files.surfaces.mjs:
// Registered-surface measurement for one arm, with no model call.
//
// Imports the arm's own plugin, runs its setup against a fake context, and
// records the exact native description the host receives plus the schema
// annotation payload the model reads alongside it.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const [armDir, outPath] = process.argv.slice(2);
if (!armDir || !outPath) {
    console.error("usage: surfaces.mjs <arm-dir> <out.json>");
    process.exit(2);
}

const requireFromArm = createRequire(join(armDir, "package.json"));
const effectPath = requireFromArm.resolve("effect");
const { Schema } = await import(pathToFileURL(effectPath).href);
const plugin = (
    await import(
        pathToFileURL(join(armDir, "src/index.ts")).href
    )
).default;

const bucket = { tools: [], commands: [], skills: [] };
const domain = (target) => ({
    hook: async () => ({ dispose: async () => {} }),
    transform: async (callback) => {
        callback({ add: (definition) => void target.push(definition) });
    },
});

await plugin.setup({
    options: {},
    location: { directory: armDir },
    tool: domain(bucket.tools),
    command: domain(bucket.commands),
    skill: domain(bucket.skills),
    session: {
        hook: async () => ({ dispose: async () => {} }),
        prompt: async () => {},
    },
});

const native = bucket.tools.find((tool) => tool.name === "docs");
const twin = bucket.tools.find((tool) => tool.name === "docs_search");
if (native === undefined) throw new Error("native docs tool not registered");

const document = Schema.toJsonSchemaDocument(native.input);
const found = [];
const seen = new Set();
const walk = (node) => {
    if (typeof node !== "object" || node === null || seen.has(node)) return;
    seen.add(node);
    if (typeof node.description === "string") found.push(node.description);
    for (const value of Object.values(node)) {
        if (Array.isArray(value)) value.forEach(walk);
        else walk(value);
    }
};
walk(document.schema);

const hash = (text) =>
    createHash("sha256").update(text, "utf8").digest("hex");
const nativeDescription = native.description;
const annotationText = found.join(" ");

const record = {
    armDir,
    nativeChars: [...nativeDescription].length,
    nativeHash: hash(nativeDescription),
    native: nativeDescription,
    twinChars: [...(twin?.description ?? "")].length,
    twinHash: hash(twin?.description ?? ""),
    annotationChars: annotationText.length,
    annotationHash: hash(annotationText),
    combinedChars: nativeDescription.length + annotationText.length,
    toolNames: bucket.tools.map((tool) => tool.name).sort(),
    skillDescriptions: bucket.skills.map((skill) => skill.description),
};
writeFileSync(outPath, `${JSON.stringify(record, null, 2)}\n`);
console.log(
    `${armDir}: native ${record.nativeChars} ${record.nativeHash}; combined ${record.combinedChars}`,
);

