// Delivery probe: capture the exact provider request body one trial-shaped
// session sends, so the registered tool payload can be compared with the
// description bytes the arm registered. Readiness only; the provider is a
// local fake and no real model is called.
import { createServer } from "node:http";
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const [capturePath, armDir, model, prompt, portArg] = process.argv.slice(2);
const port = Number(portArg ?? 8799);
let captured = 0;

const server = createServer((request, response) => {
    let raw = "";
    request.on("data", (chunk) => {
        raw += chunk;
    });
    request.on("end", () => {
        captured += 1;
        writeFileSync(
            join(dirname(capturePath), `request-${captured}.json`),
            raw,
            "utf8",
        );
        let body = {};
        try {
            body = JSON.parse(raw);
        } catch {
            /* keep the raw capture */
        }
        const text = "Hello.";
        if (body.stream === true || body.stream_options) {
            response.writeHead(200, {
                "content-type": "text/event-stream",
                "cache-control": "no-cache",
                connection: "keep-alive",
            });
            const chunk = {
                id: "chatcmpl-probe",
                object: "chat.completion.chunk",
                created: Math.floor(Date.now() / 1000),
                model: body.model ?? model,
                choices: [
                    {
                        index: 0,
                        delta: { role: "assistant", content: text },
                        finish_reason: null,
                    },
                ],
            };
            response.write(`data: ${JSON.stringify(chunk)}\n\n`);
            response.write(
                `data: ${JSON.stringify({
                    ...chunk,
                    choices: [{ index: 0, delta: {}, finish_reason: "stop" }],
                })}\n\n`,
            );
            response.write("data: [DONE]\n\n");
            response.end();
            return;
        }
        const payload = {
            id: "chatcmpl-probe",
            object: "chat.completion",
            created: Math.floor(Date.now() / 1000),
            model: body.model ?? model,
            choices: [
                {
                    index: 0,
                    message: { role: "assistant", content: text },
                    finish_reason: "stop",
                },
            ],
            usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
        };
        response.writeHead(200, { "content-type": "application/json" });
        response.end(JSON.stringify(payload));
    });
});

server.listen(port, "127.0.0.1", async () => {
    const configHome = join(dirname(capturePath), "config-home");
    mkdirSync(join(configHome, "opencode"), { recursive: true });
    writeFileSync(
        join(configHome, "opencode", "opencode.json"),
        JSON.stringify(
            {
                $schema: "https://opencode.ai/config.json",
                model,
                plugins: [{ package: "/repo", options: { lakes: [] } }],
                permissions: [
                    { action: "shell", resource: "*", effect: "deny" },
                    { action: "edit", resource: "*", effect: "deny" },
                ],
            },
            null,
            2,
        ) + "\n",
        "utf8",
    );
    const work = join(dirname(capturePath), "work");
    mkdirSync(work, { recursive: true });
    const overlay = JSON.stringify({
        providers: {
            "opencode-go": {
                settings: { baseURL: `http://127.0.0.1:${port}/v1` },
            },
        },
    });
    const child = spawn(
        "podman",
        [
            "run",
            "--rm",
            "--network",
            "host",
            "--userns=keep-id",
            "--read-only",
            "--tmpfs",
            "/tmp:rw,nosuid,size=512m",
            "-v",
            `${dirname(capturePath)}:${dirname(capturePath)}:rw`,
            "-v",
            `${armDir}:/repo:ro`,
            "-w",
            work,
            "-e",
            `PWD=${work}`,
            "-e",
            `XDG_CONFIG_HOME=${configHome}`,
            "-e",
            "XDG_DATA_HOME=/tmp/agent-home/.local/share",
            "-e",
            "XDG_CACHE_HOME=/tmp/agent-home/.cache",
            "-e",
            "HOME=/tmp/agent-home",
            "-e",
            `OPENCODE_CONFIG_CONTENT=${overlay}`,
            "localhost/opencode-placement-trials",
            "opencode",
            "run",
            "--standalone",
            "--auto",
            "--archived",
            "--title",
            "delivery-probe",
            "--model",
            model,
            "--format",
            "json",
            prompt,
        ],
        { stdio: ["ignore", "pipe", "pipe"] },
    );
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
        stdout += chunk;
    });
    child.stderr.on("data", (chunk) => {
        stderr += chunk;
    });
    const timer = setTimeout(() => child.kill("SIGKILL"), 180000);
    const status = await new Promise((resolve) => {
        child.on("exit", (code) => resolve(code));
        child.on("error", () => resolve(null));
    });
    clearTimeout(timer);
    writeFileSync(
        join(dirname(capturePath), "probe-stdout.jsonl"),
        stdout,
        "utf8",
    );
    writeFileSync(
        join(dirname(capturePath), "probe-stderr.log"),
        stderr,
        "utf8",
    );
    console.log(`exit ${status}; captured ${captured} request(s)`);
    server.close();
    process.exit(captured > 0 ? 0 : 1);
});

files.freeze.mjs:
// Freeze every identity the screen depends on before any scored session.
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import {
    existsSync,
    readFileSync,
    readdirSync,
    statSync,
    writeFileSync,
} from "node:fs";
import { join } from "node:path";
import {
    deliveredToolDescription,
    freezeExperiment,
} from "../runner/freeze.ts";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const MAIN = process.env.CAMPAIGN_SOURCE_REPO ?? process.cwd();
const EVIDENCE = join(ROOT, "evidence");
const MODEL = "opencode-go/deepseek-v4.1-flash";
const STOPPING_RULES = [
    "stop on the first unusable assessment",
    "stop on a broken premise or changed immutable input",
    "stop at the frozen trial and judge ceilings",
];

const hash = (path) =>
    createHash("sha256").update(readFileSync(path)).digest("hex");
const hashText = (text) =>
    createHash("sha256").update(text, "utf8").digest("hex");
const git = (repo, ...args) =>
    execFileSync("git", ["-C", repo, ...args], { encoding: "utf8" }).trim();
const json = (path) => JSON.parse(readFileSync(path, "utf8"));
const text = (path) => readFileSync(path, "utf8");

/** Every file under a directory, recursively, sorted. */
const filesUnder = (dir) => {
    if (!existsSync(dir)) return [];
    const found = [];
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const path = join(dir, entry.name);
        if (entry.isDirectory()) found.push(...filesUnder(path));
        else if (entry.isFile()) found.push(path);
    }
    return found.sort();
};

/** Hash one absolute path as a root-relative immutable input. */
const frozenFile = (path) => ({
    path: path.slice(ROOT.length + 1),
    sha256: hash(path),
});
const capture = (command, args) => {
    try {
        return execFileSync(command, args, { encoding: "utf8" }).trim();
    } catch (error) {
        return `unavailable: ${String(error)}`;
    }
};

const schedule = json(join(ROOT, "evidence/schedule.json"));
const scenarios = [
    "R01",
    "S02",
    "R02",
    "R03",
    "S05",
    "S06",
    "S07",
    "R04",
];

const arm = (letter) => {
    const repo = join(ROOT, "arms", letter);
    const surfaces = json(join(ROOT, `evidence/surfaces-${letter}.json`));
    // The provider request the delivery probe actually received. No
    // hand-extracted copy: the served description is read from the payload.
    const probe = json(
        join(ROOT, `evidence/delivery-${letter}/request-1.json`),
    );
    const served = deliveredToolDescription(probe);
    if (served.delivered === undefined) {
        throw new Error(
            `delivery ${letter}: ${served.problem ?? "no served description"}`,
        );
    }
    const delivery = {
        model: probe.model ?? null,
        nativeChars: served.delivered.chars,
        nativeHash: served.delivered.sha256,
    };
    const generations = Object.fromEntries(
        scenarios.map((id) => {
            const record = json(
                join(ROOT, `gen/${letter}/fixtures/${id}/generation.json`),
            );
            return [
                id,
                {
                    pluginHash: record.pluginHash,
                    inputsHash: record.inputsHash,
                    promptHash: record.outputs?.promptHash ?? null,
                },
            ];
        }),
    );
    return {
        repo,
        commit: git(repo, "rev-parse", "HEAD"),
        tree: git(repo, "rev-parse", "HEAD^{tree}"),
        clean: git(repo, "status", "--porcelain") === "",
        srcIndexSha256: hash(join(repo, "src/index.ts")),
        surfaces,
        delivery,
        generations,
    };
};

const prompts = Object.fromEntries(
    scenarios.map((id) => [
        id,
        {
            a: hash(join(ROOT, "gen/a/prompts", `${id}.md`)),
            b: hash(join(ROOT, "gen/b/prompts", `${id}.md`)),
        },
    ]),
);

const identities = {
    campaign: schedule.campaign,
    frozenAt: new Date().toISOString(),
    base: {
        repo: MAIN,
        branch: git(MAIN, "rev-parse", "--abbrev-ref", "HEAD"),
        commit: git(MAIN, "rev-parse", "HEAD"),
        tree: git(MAIN, "rev-parse", "HEAD^{tree}"),
        clean: git(MAIN, "status", "--porcelain") === "",
    },
    arms: { A: arm("a"), B: arm("b") },
    measurement: {
        repo: join(ROOT, "measurement"),
        commit: git(join(ROOT, "measurement"), "rev-parse", "HEAD"),
        tree: git(join(ROOT, "measurement"), "rev-parse", "HEAD^{tree}"),
        clean: git(join(ROOT, "measurement"), "status", "--porcelain") === "",
        files: {
            acScoring: hash(
                join(
                    ROOT,
                    "measurement/tests/fixtures/placement-harness/ac-scoring.mts",
                ),
            ),
            acRunner: hash(
                join(
                    ROOT,
                    "measurement/tests/fixtures/placement-harness/ac/run.mjs",
                ),
            ),
            judgeLauncher: hash(
                join(
                    ROOT,
                    "measurement/tests/fixtures/placement-harness/ac/judge-launcher.sh",
                ),
            ),
            analyser: hash(
                join(
                    ROOT,
                    "measurement/tests/fixtures/placement-harness/analysis/analyse.mts",
                ),
            ),
            driver: hash(join(ROOT, "prepare/run.mjs")),
            manifest: hash(join(ROOT, "prepare/manifest.json")),
        },
    },
    corpus: {
        path: join(
            ROOT,
            "arms/a/tests/fixtures/placement-harness/prod014/cases.json",
        ),
        sha256: hash(
            join(
                ROOT,
                "arms/a/tests/fixtures/placement-harness/prod014/cases.json",
            ),
        ),
        bSha256: hash(
            join(
                ROOT,
                "arms/b/tests/fixtures/placement-harness/prod014/cases.json",
            ),
        ),
    },
    truth: {
        sha256: hash(
            join(
                ROOT,
                "arms/a/tests/fixtures/placement-harness/prod014/truth.json",
            ),
        ),
    },
    measurementSpec: {
        path: join(ROOT, "evidence/measurement-spec.json"),
        sha256: hash(join(ROOT, "evidence/measurement-spec.json")),
    },
    schedule: {
        path: join(ROOT, "evidence/schedule.json"),
        slotsSha256: hashText(JSON.stringify(schedule.slots)),
        fileSha256: hash(join(ROOT, "evidence/schedule.json")),
        slots: schedule.slots.length,
        pairs: new Set(schedule.slots.map((slot) => slot.pairId)).size,
    },
    prompts,
    primaryChecks: Object.fromEntries(
        ["R01", "S02", "R02", "R03", "S05", "S06", "S07", "R04"].map((id) => {
            const found = json(
                join(
                    ROOT,
                    "arms/a/tests/fixtures/placement-harness/prod014/cases.json",
                ),
            ).find((entry) => entry.id === id);
            return [
                id,
                hash(
                    join(
                        ROOT,
                        "arms/a/tests/fixtures/placement-harness/primary-checks",
                        found.primaryCheck.script,
                    ),
                ),
            ];
        }),
    ),
    models: {
        trial: "opencode-go/deepseek-v4.1-flash",
        trialName: "DeepSeek V4.1 Flash 1017 (catalogue)",
        trialVariant: "none selected; catalogue variants low/high/max",
        judge: "zai-coding-plan/glm-5.3-flash",
    },
    runtime: {
        hostOpencode: capture("opencode", ["--version"]),
        node: process.version,
        image: "localhost/opencode-placement-trials",
        imageId: capture("podman", [
            "image",
            "inspect",
            "--format",
            "{{.Id}}",
            "localhost/opencode-placement-trials",
        ]),
        containerOpencode: capture("podman", [
            "run",
            "--rm",
            "localhost/opencode-placement-trials",
            "opencode",
            "--version",
        ]),
    },
    budget: {
        plannedTrials: 16,
        plannedJudgeAttempts: 16,
        trialTimeoutMs: 600000,
        judgeTimeoutMs: 600000,
        workers: 1,
    },
};

const problems = [];
for (const [id, pair] of Object.entries(prompts)) {
    if (pair.a !== pair.b) problems.push(`prompt differs between arms: ${id}`);
}
if (identities.corpus.sha256 !== identities.corpus.bSha256)
    problems.push("corpus differs between arms");
if (identities.arms.A.surfaces.nativeHash === identities.arms.B.surfaces.nativeHash)
    problems.push("A and B descriptions are identical");
if (
    identities.arms.A.delivery.model !== MODEL ||
    identities.arms.B.delivery.model !== MODEL
) {
    problems.push("a delivery probe served a different model");
}
if (
    identities.arms.A.delivery.nativeHash !==
    identities.arms.A.surfaces.nativeHash
)
    problems.push("A delivered description differs from the registered one");
if (
    identities.arms.B.delivery.nativeHash !==
    identities.arms.B.surfaces.nativeHash
)
    problems.push("B delivered description differs from the registered one");
if (problems.length > 0) {
    console.error(problems.join("\n"));
    process.exit(1);
}

const armFreeze = (letter) => ({
    id: letter.toUpperCase(),
    commit: identities.arms[letter.toUpperCase()].commit,
    tree: identities.arms[letter.toUpperCase()].tree,
    clean: identities.arms[letter.toUpperCase()].clean,
    descriptionChars:
        identities.arms[letter.toUpperCase()].surfaces.nativeChars,
    descriptionHash:
        identities.arms[letter.toUpperCase()].surfaces.nativeHash,
    deliveredChars:
        identities.arms[letter.toUpperCase()].delivery.nativeChars,
    deliveredHash: identities.arms[letter.toUpperCase()].delivery.nativeHash,
    annotationChars:
        identities.arms[letter.toUpperCase()].surfaces.annotationChars,
    annotationHash:
        identities.arms[letter.toUpperCase()].surfaces.annotationHash,
});

const immutable = [
    ...filesUnder(join(ROOT, "prepare")),
    ...filesUnder(join(ROOT, "runner")),
    ...["a", "b"].flatMap((letter) => [
        join(ROOT, `evidence/surfaces-${letter}.json`),
        join(ROOT, `evidence/delivery-${letter}/request-1.json`),
        join(ROOT, `gen/${letter}/prompts`),
        join(ROOT, `gen/${letter}/fixtures`),
    ]),
    join(EVIDENCE, "schedule.json"),
    join(EVIDENCE, "measurement-spec.json"),
    join(ROOT, "arms/a/tests/fixtures/placement-harness/prod014/cases.json"),
    join(ROOT, "arms/a/tests/fixtures/placement-harness/prod014/truth.json"),
    join(ROOT, "arms/a/tests/fixtures/placement-harness/primary-checks"),
].flatMap((path) =>
    statSync(path).isDirectory() ? filesUnder(path) : [path],
);

const started =
    ["a", "b"].some((letter) => {
        const dir = join(ROOT, `gen/${letter}/results`);
        return existsSync(dir) && readdirSync(dir).length > 0;
    }) ||
    (existsSync(join(EVIDENCE, "ATTEMPTS.jsonl")) &&
        text(join(EVIDENCE, "ATTEMPTS.jsonl")).trim() !== "");

const decision = freezeExperiment({
    campaign: identities.campaign,
    sourceRevision: identities.base.commit,
    sourceTree: identities.base.tree,
    imageId: identities.runtime.imageId,
    containerCli: identities.runtime.containerOpencode,
    measurementSha256: identities.measurementSpec.sha256,
    arms: [armFreeze("a"), armFreeze("b")],
    files: immutable.map(frozenFile),
    stoppingRules: STOPPING_RULES,
    ceilings: {
        trial: identities.budget.plannedTrials,
        judge: identities.budget.plannedJudgeAttempts,
    },
    started,
    frozen:
        existsSync(join(EVIDENCE, "FROZEN.json")) ||
        existsSync(join(EVIDENCE, "frozen-identities.json")),
});

if (!decision.ok) {
    console.error(decision.problems.join("\n"));
    process.exit(1);
}

writeFileSync(
    join(ROOT, "evidence/frozen-identities.json"),
    `${JSON.stringify(identities, null, 2)}\n`,
    { encoding: "utf8", flag: "wx" },
);
writeFileSync(
    join(ROOT, "evidence/FROZEN.json"),
    `${JSON.stringify(
        {
            campaign: identities.campaign,
            frozenAt: identities.frozenAt,
            baseCommit: identities.base.commit,
            armA: identities.arms.A.commit,
            armB: identities.arms.B.commit,
            measurement: identities.measurement.commit,
            scheduleSha256: identities.schedule.slotsSha256,
            corpusSha256: identities.corpus.sha256,
            promptsIdentical: true,
            trialModel: identities.models.trial,
            judgeModel: identities.models.judge,
            imageId: identities.runtime.imageId,
            budget: identities.budget,
            freeze: decision.record,
        },
        null,
        2,
    )}\n`,
    { encoding: "utf8", flag: "wx" },
);
console.log(
    `frozen: A ${identities.arms.A.surfaces.nativeChars} ${identities.arms.A.surfaces.nativeHash}; B ${identities.arms.B.surfaces.nativeChars} ${identities.arms.B.surfaces.nativeHash}; ${identities.schedule.slots} slots`,
);

files.run.mjs:
// Paired productivity-screen runner for the 0.14.0 description comparison.
//
// Safety properties:
// - The schedule and frozen identities must exist before any launch.
// - A launch record is written before the model session starts. It is never
//   overwritten, so a resume cannot relaunch an attempt whose model call may
//   have begun.
// - An existing result directory without meta.json is a started attempt, not
//   a blank slot; it blocks and is reported.
// - The judge runs only for a recorded, usable trial, and ac/run.mjs claims
//   its attempt directory before spawning the judge model.
// - Gate and judge run from the independent measurement worktree.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
    accessSync,
    appendFileSync,
    constants,
    existsSync,
    mkdirSync,
    readFileSync,
    readdirSync,
    writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { loadJudgeKey } from "./env.mjs";
import { parseCampaignLedger } from "../runner/ledger.ts";
import {
    advanceClaim,
    claimBudget,
    readClaims,
    restartDisposition,
} from "../runner/budget.ts";
import { resolveAttemptSelection } from "../runner/selector.ts";
import { verifyFreeze } from "../runner/freeze.ts";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const MAIN = process.env.CAMPAIGN_SOURCE_REPO ?? process.cwd();
const MODEL = "opencode-go/deepseek-v4.1-flash";
const JUDGE = "zai-coding-plan/glm-5.3-flash";
const TRIAL_TIMEOUT = 600000;
const JUDGE_TIMEOUT = 600000;
const SHIM = join(ROOT, "prepare/shim");
const EVIDENCE = join(ROOT, "evidence");
const LEDGER = join(EVIDENCE, "ATTEMPTS.jsonl");
const LAUNCHES = join(EVIDENCE, "launches");
const TRIAL_LOGS = join(ROOT, "logs/trials");
const CONTAINER_LOGS = join(ROOT, "logs/containers");
const MEASUREMENT = join(ROOT, "measurement");

const argv = process.argv.slice(2);
const flag = (name) =>
    argv.includes(name) ? argv[argv.indexOf(name) + 1] : undefined;
const dryRun = argv.includes("--dry-run");
const trialCommand = flag("--trial-command");
const pairFrom = Number(flag("--pair-from") ?? 1);
const pairTo = Number(flag("--pair-to") ?? 8);
const judgeKeySource = loadJudgeKey(ROOT);

const fail = (message) => {
    console.error(`BLOCKER: ${message}`);
    process.exit(2);
};

const readJson = (path) =>
    existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : null;
const readText = (path) => (existsSync(path) ? readFileSync(path, "utf8") : "");

/** The parsed ledger: absence is a state, never an empty trusted ledger. */
const ledgerParse = () =>
    parseCampaignLedger(existsSync(LEDGER) ? readText(LEDGER) : undefined);

/** Why spend is refused now, or null when a clean open ledger permits it. */
const spendRefusal = () => {
    const parsed = ledgerParse();
    if (parsed.state === "malformed") {
        return `attempt ledger is malformed: ${parsed.problems.join("; ")}`;
    }
    if (parsed.state === "closed") {
        return "campaign is closed; no launch event or child process is permitted";
    }
    return null;
};

/** Whether the container logging shim can actually be executed. */
const shimExecutable = () => {
    try {
        accessSync(join(SHIM, "podman"), constants.X_OK);
        return true;
    } catch {
        return false;
    }
};
const ledger = (entry) => {
    appendFileSync(
        LEDGER,
        `${JSON.stringify({ at: new Date().toISOString(), ...entry })}\n`,
        "utf8",
    );
};

const schedule = readJson(join(EVIDENCE, "schedule.json"));
if (schedule === null) fail("no frozen schedule; run prepare/schedule.mjs first");
const slots = schedule.slots;

const manifest = readJson(join(ROOT, "prepare/manifest.json"));
const selection = resolveAttemptSelection({
    manifestAttemptId: manifest?.assessment?.attemptId ?? null,
    overrideAttemptId: flag("--attempt-id") ?? null,
});
if (!selection.ok) {
    console.error(`BLOCKER: ${selection.problems.join("; ")}`);
    process.exit(2);
}
const attemptId = selection.selection.attemptId;

const frozen = readJson(join(EVIDENCE, "FROZEN.json"));
const ceilings = {
    trial: Number(frozen?.budget?.plannedTrials ?? 16),
    judge: Number(frozen?.budget?.plannedJudgeAttempts ?? 16),
};

/** Capture one external command's trimmed output, or an empty string. */
const capture = (command, args) => {
    const result = spawnSync(command, args, { encoding: "utf8" });
    return result.status === 0 ? String(result.stdout ?? "").trim() : "";
};

/**
 * Verify the frozen premise against what this invocation would actually use:
 * every immutable input, the source revision, the image identity and the
 * container CLI. A historical freeze without a record returns no problems.
 */
const premiseProblems = () => {
    const record = frozen?.freeze;
    if (!record) return [];
    const files = record.files.map((file) => {
        const path = join(ROOT, file.path);
        return {
            path: file.path,
            sha256: existsSync(path)
                ? createHash("sha256").update(readFileSync(path)).digest("hex")
                : "missing",
        };
    });
    return verifyFreeze(record, {
        files,
        imageId: capture("podman", [
            "image",
            "inspect",
            "--format",
            "{{.Id}}",
            "localhost/opencode-placement-trials",
        ]),
        containerCli: capture("podman", [
            "run",
            "--rm",
            "localhost/opencode-placement-trials",
            "opencode",
            "--version",
        ]),
        sourceRevision: safeHead(MAIN),
    });
};

const armPaths = (arm) => {
    const letter = arm.toLowerCase();
    return {
        repo: join(ROOT, "arms", letter),
        base: join(ROOT, "gen", letter),
        cases: join(
            ROOT,
            "arms",
            letter,
            "tests/fixtures/placement-harness/prod014/cases.json",
        ),
    };
};

const resultDir = (slot) => {
    const { base } = armPaths(slot.arm);
    return join(base, "results", slot.stamp, slot.scenario);
};

const truthPath = join(
    ROOT,
    "arms/a/tests/fixtures/placement-harness/prod014/truth.json",
);
const specPath = join(EVIDENCE, "measurement-spec.json");

const attemptsOf = (stamp) => {
    const dir = join(LAUNCHES, stamp);
    if (!existsSync(dir)) return [];
    return readdirSync(dir)
        .filter((name) => /^attempt-\d{3}\.json$/.test(name))
        .sort()
        .map((name) => ({
            id: name.replace(/\.json$/, ""),
            record: readJson(join(dir, name)),
        }));
};

const newAttempt = (slot, status, extra = {}) => {
    const dir = join(LAUNCHES, slot.stamp);
    mkdirSync(dir, { recursive: true });
    const previous = attemptsOf(slot.stamp);
    const attemptId = `attempt-${String(previous.length + 1).padStart(3, "0")}`;
    const record = {
        campaign: schedule.campaign,
        attemptId,
        slot: slot.slot,
        pairId: slot.pairId,
        repetition: slot.repetition,
        scenario: slot.scenario,
        arm: slot.arm,
        stamp: slot.stamp,
        status,
        launchedAt: new Date().toISOString(),
        ...extra,
    };
    writeFileSync(
        join(dir, `${attemptId}.json`),
        `${JSON.stringify(record, null, 2)}\n`,
        { encoding: "utf8", flag: "wx" },
    );
    return record;
};

const updateAttempt = (slot, attemptId, patch) => {
    const path = join(LAUNCHES, slot.stamp, `${attemptId}.json`);
    const current = readJson(path);
    if (current === null) throw new Error(`missing attempt record ${path}`);
    writeFileSync(
        path,
        `${JSON.stringify({ ...current, ...patch }, null, 2)}\n`,
        "utf8",
    );
};

const containerRunObserved = (logPath) =>
    /^\S+ run(?:\s|$)/m.test(readText(logPath));

const usableRun = (meta) =>
    meta !== null &&
    meta.exit === 0 &&
    meta.signal === null &&
    meta.timedOut !== true &&
    meta.outputOverflow !== true &&
    meta.answerValid === true;

const hasJudgement = (dir) => {
    const judgement = readJson(join(dir, "ac", attemptId, "judgement.json"));
    if (judgement?.status === "judged") return true;
    const resolution = readJson(join(dir, "ac", attemptId, "resolution.json"));
    return resolution?.status === "judged";
};

const safeHead = (repo) => {
    const result = spawnSync("git", ["-C", repo, "rev-parse", "HEAD"], {
        encoding: "utf8",
    });
    return result.status === 0 ? result.stdout.trim() : "";
};

const envFor = (slot) => {
    const { repo, base, cases } = armPaths(slot.arm);
    return {
        ...process.env,
        PATH: `${SHIM}:${process.env.PATH ?? ""}`,
        CONTAINER_LOG: join(CONTAINER_LOGS, `${slot.stamp}.log`),
        PLACEMENT_CASES: cases,
        PLACEMENT_PROMPTS: join(base, "prompts"),
        PLACEMENT_FIXTURES: join(base, "fixtures"),
        PLACEMENT_RUBRICS: join(base, "rubrics"),
        PLACEMENT_RESULTS: join(base, "results"),
        PLACEMENT_RUN_FIXTURES: join(base, "run-fixtures"),
        PLACEMENT_PLUGIN_COMMIT: safeHead(repo),
        TRIAL_TIMEOUT_MS: String(TRIAL_TIMEOUT),
    };
};

const dry = () => {
    const problems = [];
    if (slots.length !== 16) problems.push(`expected 16 slots, ${slots.length}`);
    for (let index = 0; index < slots.length; index += 2) {
        const first = slots[index];
        const second = slots[index + 1];
        if (!first || !second) {
            problems.push(`unpaired slot at index ${index}`);
            continue;
        }
        if (first.pairId !== second.pairId)
            problems.push(`pair split at ${first.slot}/${second.slot}`);
        if (first.arm === second.arm)
            problems.push(`pair ${first.pairId} repeats arm ${first.arm}`);
        if (first.scenario !== second.scenario)
            problems.push(`pair ${first.pairId} mixes scenarios`);
    }
    const stamps = new Set();
    for (const slot of slots) {
        const { repo, base, cases } = armPaths(slot.arm);
        if (stamps.has(slot.stamp)) problems.push(`duplicate stamp ${slot.stamp}`);
        stamps.add(slot.stamp);
        for (const [label, path] of [
            ["arm repo", join(repo, "src/index.ts")],
            ["lockfile", join(repo, "package-lock.json")],
            ["container runner", join(repo, "tests/fixtures/placement-harness/container-run.sh")],
            ["judge launcher", join(MEASUREMENT, "tests/fixtures/placement-harness/ac/judge-launcher.sh")],
            ["corpus", cases],
            ["generated fixture", join(base, "fixtures", slot.scenario, "generation.json")],
            ["prompt", join(base, "prompts", `${slot.scenario}.md`)],
            ["rubric", join(base, "rubrics", slot.scenario)],
        ]) {
            if (!existsSync(path)) problems.push(`${slot.stamp}: missing ${label} (${path})`);
        }
        if (attemptsOf(slot.stamp).length > 0)
            problems.push(`${slot.stamp}: launch records already exist`);
        if (existsSync(join(base, "results", slot.stamp)))
            problems.push(`${slot.stamp}: result directory already exists`);
    }
    for (const path of [
        join(EVIDENCE, "frozen-identities.json"),
        join(EVIDENCE, "schedule.json"),
        specPath,
        truthPath,
        join(SHIM, "podman"),
    ]) {
        if (!existsSync(path)) problems.push(`missing ${path}`);
    }
    try {
        accessSync(join(SHIM, "podman"), constants.X_OK);
    } catch {
        problems.push(
            `container logging shim is not executable: ${join(SHIM, "podman")}`,
        );
    }
    if (!existsSync(join(EVIDENCE, "FROZEN.json")))
        problems.push("missing evidence/FROZEN.json");
    console.log(
        slots
            .map(
                (slot) =>
                    `slot ${String(slot.slot).padStart(2)} ${slot.pairId} ${slot.scenario} ${slot.arm} ${slot.stamp}`,
            )
            .join("\n"),
    );
    if (problems.length > 0) {
        console.error(problems.join("\n"));
        process.exit(1);
    }
    console.log(`\ndry run: ${slots.length} slots, 8 adjacent pairs, no model session`);
};

const runTrial = (slot, attempt) => {
    const dir = resultDir(slot);
    const containerLog = join(CONTAINER_LOGS, `${slot.stamp}.log`);
    mkdirSync(TRIAL_LOGS, { recursive: true });
    mkdirSync(CONTAINER_LOGS, { recursive: true });
    writeFileSync(containerLog, "", "utf8");
    const command =
        trialCommand ??
        join(
            ROOT,
            "arms",
            slot.arm.toLowerCase(),
            "tests/fixtures/placement-harness/container-run.sh",
        );
    const started = new Date().toISOString();
    ledger({
        event: "launch",
        attemptId: attempt.attemptId,
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        command,
    });
    const result = spawnSync(
        command,
        [
            "run",
            slot.scenario,
            "--stamp",
            slot.stamp,
            "--model",
            MODEL,
            "--print-logs",
        ],
        {
            env: envFor(slot),
            encoding: "utf8",
            timeout: TRIAL_TIMEOUT + 120000,
            maxBuffer: 64 * 1024 * 1024,
            shell: trialCommand !== undefined && trialCommand.endsWith(".sh"),
        },
    );
    const finished = new Date().toISOString();
    writeFileSync(
        join(TRIAL_LOGS, `${slot.stamp}.log`),
        `# stdout\n${result.stdout ?? ""}\n# stderr\n${result.stderr ?? ""}\n`,
        "utf8",
    );
    const meta = readJson(join(dir, "meta.json"));
    const containerRun = containerRunObserved(containerLog);
    const usable = usableRun(meta);
    const startedAttempt = meta !== null || existsSync(dir);
    updateAttempt(slot, attempt.attemptId, {
        status:
            meta !== null
                ? "recorded"
                : startedAttempt
                  ? "attempted-unknown"
                  : "pre-model-failure",
        exit: result.status,
        signal: result.signal,
        timedOut: result.error?.code === "ETIMEDOUT",
        startedAt: started,
        finishedAt: finished,
        containerRun,
        resultDir: dir,
        resultRecorded: meta !== null,
        usable,
    });
    ledger({
        event: "trial-exit",
        attemptId: attempt.attemptId,
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        exit: result.status,
        signal: result.signal,
        startedAt: started,
        finishedAt: finished,
        containerRun,
        resultRecorded: meta !== null,
        usable,
    });
    return {
        meta,
        containerRun,
        usable,
        exit: result.status,
        signal: result.signal,
    };
};

const runGate = (slot) => {
    const { base, cases } = armPaths(slot.arm);
    const result = spawnSync(
        process.execPath,
        [
            join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs"),
            "gate",
            "--repo", MEASUREMENT,
            "--base", base,
            "--cases", cases,
            "--stamps", slot.stamp,
        ],
        { env: envFor(slot), encoding: "utf8", timeout: 300000 },
    );
    const gate = readJson(join(resultDir(slot), "gate.json"));
    ledger({
        event: "gate",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        exit: result.status,
        status: gate?.status ?? "missing",
        reason: gate?.reason ?? null,
    });
    return gate;
};

const runJudge = (slot) => {
    const { base } = armPaths(slot.arm);
    const attemptDir = join(resultDir(slot), "ac", attemptId);
    if (hasJudgement(resultDir(slot))) {
        ledger({
            event: "judge-skipped-existing",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            attemptDir,
        });
        return true;
    }
    const unsettledJudge = readClaims(EVIDENCE, "judge").find(
        (claim) =>
            claim.stamp === slot.stamp &&
            restartDisposition(claim) !== null,
    );
    if (unsettledJudge !== undefined) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: "unsettled judge claim from an interrupted invocation",
        });
        console.error(
            `BLOCKER: ${slot.stamp} has an unsettled judge claim; preserve and report`,
        );
        return false;
    }
    const claim = claimBudget(EVIDENCE, "judge", ceilings.judge, {
        stamp: slot.stamp,
        attemptId,
    });
    if (!claim.ok) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            pairId: slot.pairId,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: claim.reason,
        });
        console.error(`BLOCKER: ${claim.reason}`);
        return false;
    }
    ledger({
        event: "judge-launch",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        attemptDir,
    });
    advanceClaim(claim.claim, "spawned");
    const result = spawnSync(
        process.execPath,
        [
            join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs"),
            "judge",
            "--base", base,
            "--stamp", slot.stamp,
            "--case", slot.scenario,
            "--truth", truthPath,
            "--spec", specPath,
            "--attempt", attemptId,
            "--launcher", join(MEASUREMENT, "tests/fixtures/placement-harness/ac/judge-launcher.sh"),
            "--model", JUDGE,
            "--workdir", join(EVIDENCE, "ac-runs"),
            "--timeout", String(JUDGE_TIMEOUT),
        ],
        {
            env: envFor(slot),
            encoding: "utf8",
            timeout: JUDGE_TIMEOUT + 120000,
        },
    );
    const resolve = spawnSync(
        process.execPath,
        [
            join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs"),
            "resolve",
            "--base", base,
            "--spec", specPath,
        ],
        { env: envFor(slot), encoding: "utf8", timeout: 120000 },
    );
    advanceClaim(claim.claim, "closed");
    const judgement = readJson(join(attemptDir, "judgement.json"));
    const resolution = readJson(join(attemptDir, "resolution.json"));
    const status =
        resolution?.status === "judged"
            ? "judged-after-resolve"
            : judgement?.status ?? "missing";
    ledger({
        event: "judge-exit",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        exit: result.status,
        resolveExit: resolve.status,
        status,
        outcome:
            judgement?.documentationOutcome ??
            resolution?.parsed?.documentationOutcome ??
            null,
        retrieval:
            judgement?.retrievalApplication?.state ??
            resolution?.parsed?.retrievalApplication?.state ??
            null,
        attemptDir,
    });
    return status === "judged" || status === "judged-after-resolve";
};

const finishRecordedSlot = (slot, meta) => {
    if (!existsSync(join(resultDir(slot), "gate.json"))) runGate(slot);
    if (!usableRun(meta)) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: "recorded trial is not usable",
        });
        console.error(`BLOCKER: ${slot.stamp} recorded an unusable trial`);
        return "blocked";
    }
    const judged = runJudge(slot);
    if (!judged) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            pairId: slot.pairId,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: "no usable judgement; campaign paused",
        });
        console.error(
            `BLOCKER: ${slot.stamp} has no usable ${attemptId} judgement`,
        );
        return "blocked";
    }
    ledger({
        event: "slot-complete",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        judged,
    });
    return "complete";
};

const processSlot = (slot) => {
    const dir = resultDir(slot);
    const unsettledTrial = readClaims(EVIDENCE, "trial").find(
        (claim) =>
            claim.stamp === slot.stamp &&
            restartDisposition(claim) !== null,
    );
    if (unsettledTrial !== undefined) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: "unsettled trial claim from an interrupted invocation",
        });
        console.error(
            `BLOCKER: ${slot.stamp} has an unsettled trial claim; no duplicate call is authorised`,
        );
        return "blocked";
    }
    const attempts = attemptsOf(slot.stamp);
    const latest = attempts.at(-1);
    if (latest) {
        const meta = readJson(join(dir, "meta.json"));
        if (meta !== null) {
            return finishRecordedSlot(slot, meta);
        }
        if (existsSync(dir)) {
            ledger({
                event: "slot-blocked",
                slot: slot.slot,
                stamp: slot.stamp,
                arm: slot.arm,
                reason: "started attempt has no recorded meta.json; evidence preserved",
                attemptId: latest.id,
            });
            console.error(
                `BLOCKER: ${slot.stamp} started but has no recorded result; preserved at ${dir}`,
            );
            return "blocked";
        }
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: "pre-model failure; no replacement launch authorised",
            attemptId: latest.id,
        });
        console.error(
            `BLOCKER: ${slot.stamp} stopped before the model call; no retry authorised`,
        );
        return "blocked";
    }
    const claim = claimBudget(EVIDENCE, "trial", ceilings.trial, {
        stamp: slot.stamp,
        attemptId: "attempt-001",
    });
    if (!claim.ok) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            reason: claim.reason,
        });
        console.error(`BLOCKER: ${claim.reason}`);
        return "blocked";
    }
    const attempt = newAttempt(slot, "launching");
    advanceClaim(claim.claim, "spawned");
    const status = launchRun(slot, attempt);
    advanceClaim(claim.claim, "closed");
    return status;
};

const launchRun = (slot, attempt) => {
    const outcome = runTrial(slot, attempt);
    if (outcome.meta !== null) {
        return finishRecordedSlot(slot, outcome.meta);
    }
    if (!outcome.containerRun && !existsSync(resultDir(slot))) {
        ledger({
            event: "slot-pre-model-failure",
            slot: slot.slot,
            stamp: slot.stamp,
            arm: slot.arm,
            attemptId: attempt.attemptId,
            exit: outcome.exit,
            signal: outcome.signal,
        });
        console.error(
            `BLOCKER: ${slot.stamp} stopped before the container run; preserve and report`,
        );
        return "blocked";
    }
    ledger({
        event: "slot-attempted-unknown",
        slot: slot.slot,
        stamp: slot.stamp,
        arm: slot.arm,
        attemptId: attempt.attemptId,
        exit: outcome.exit,
        signal: outcome.signal,
    });
    console.error(
        `BLOCKER: ${slot.stamp} container ran but recorded no result; the model call may have begun`,
    );
    return "blocked";
};

if (dryRun) {
    dry();
    process.exit(0);
}

const refusal = spendRefusal();
if (refusal !== null) {
    console.error(`BLOCKER: ${refusal}`);
    process.exit(2);
}

const premise = premiseProblems();
if (premise.length > 0) {
    console.error(`BLOCKER: frozen premise changed: ${premise.join("; ")}`);
    process.exit(2);
}

if (!shimExecutable()) {
    console.error(
        `BLOCKER: container logging shim is not executable: ${join(SHIM, "podman")}`,
    );
    process.exit(2);
}

if (judgeKeySource === null) {
    console.error(
        "BLOCKER: no ZAI_API_KEY (environment, ZAI_API_KEY_FILE or campaign .env)",
    );
    process.exit(2);
}

mkdirSync(LAUNCHES, { recursive: true });
mkdirSync(EVIDENCE, { recursive: true });
ledger({
    event: "campaign-start",
    campaign: schedule.campaign,
    driver: "prepare/run.mjs",
    scheduleSha256: createHash("sha256")
        .update(JSON.stringify(slots), "utf8")
        .digest("hex"),
    model: MODEL,
    judgeModel: JUDGE,
    pairFrom,
    pairTo,
});

for (let index = 0; index < slots.length; index += 2) {
    const pair = slots.slice(index, index + 2);
    const pairNumber = Number(pair[0].pairId.slice(1));
    if (pairNumber < pairFrom || pairNumber > pairTo) continue;
    for (const slot of pair) {
        const status = processSlot(slot);
        if (status !== "complete") {
            console.error(
                `campaign paused at ${slot.stamp}; ${index} slot(s) processed`,
            );
            process.exit(2);
        }
    }
    ledger({
        event: "pair-complete",
        pairId: pair[0].pairId,
        slots: pair.map((slot) => slot.slot),
    });
    console.log(`pair ${pair[0].pairId} complete`);
}
ledger({ event: "campaign-complete", pairFrom, pairTo });
console.log("campaign range complete");

