// One recovery judgement per preserved block-1 trial, written to
// `attempt-002`. The failed `attempt-001` stays untouched.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { loadJudgeKey } from "./env.mjs";
import { parseCampaignLedger } from "../runner/ledger.ts";
import { advanceClaim, claimBudget } from "../runner/budget.ts";
import { resolveRecoverySelection } from "../runner/selector.ts";
import { verifyFreeze } from "../runner/freeze.ts";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const EVIDENCE = join(ROOT, "evidence");
const MEASUREMENT = join(ROOT, "measurement");
const AC = join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs");
const LEDGER = join(EVIDENCE, "ATTEMPTS.jsonl");
const JUDGE = "zai-coding-plan/glm-5.3-flash";
const argv = process.argv.slice(2);
const selectionFlag = (name) =>
    argv.includes(name) ? argv[argv.indexOf(name) + 1] : undefined;
const schedule = JSON.parse(
    readFileSync(join(EVIDENCE, "schedule.json"), "utf8"),
).slots;
const slots = schedule.filter((slot) => Number(slot.pairId.slice(1)) <= 4);
const readJson = (path) =>
    existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : null;
const ledger = (entry) =>
    appendFileSync(
        LEDGER,
        `${JSON.stringify({ at: new Date().toISOString(), ...entry })}\n`,
    );
const readText = (path) => (existsSync(path) ? readFileSync(path, "utf8") : "");

const manifest = readJson(join(ROOT, "prepare/manifest.json"));
const selection = resolveRecoverySelection({
    manifestAttemptId: manifest?.assessment?.attemptId ?? null,
    recoveryAttemptId: selectionFlag("--attempt-id") ?? "attempt-002",
});
if (!selection.ok) {
    console.error(`BLOCKER: ${selection.problems.join("; ")}`);
    process.exit(2);
}
const attemptId = selection.selection.attemptId;
const frozen = readJson(join(EVIDENCE, "FROZEN.json"));
const judgeCeiling = Number(frozen?.budget?.plannedJudgeAttempts ?? 16);
const MAIN = process.env.CAMPAIGN_SOURCE_REPO ?? process.cwd();
const capture = (command, args) => {
    const result = spawnSync(command, args, { encoding: "utf8" });
    return result.status === 0 ? String(result.stdout ?? "").trim() : "";
};
const premiseProblems = () => {
    const record = frozen?.freeze;
    if (!record) return [];
    const files = record.files.map((file) => {
        const path = join(ROOT, file.path);
        return {
            path: file.path,
            sha256: existsSync(path)
                ? createHash("sha256").update(readFileSync(path)).digest("hex")
                : "missing",
        };
    });
    const revision = spawnSync("git", ["-C", MAIN, "rev-parse", "HEAD"], {
        encoding: "utf8",
    });
    return verifyFreeze(record, {
        files,
        imageId: capture("podman", [
            "image",
            "inspect",
            "--format",
            "{{.Id}}",
            "localhost/opencode-placement-trials",
        ]),
        containerCli: capture("podman", [
            "run",
            "--rm",
            "localhost/opencode-placement-trials",
            "opencode",
            "--version",
        ]),
        sourceRevision:
            revision.status === 0 ? String(revision.stdout).trim() : "",
    });
};

/** The parsed ledger: a malformed or closed ledger permits no spend. */
const ledgerParse = () =>
    parseCampaignLedger(existsSync(LEDGER) ? readText(LEDGER) : undefined);

/** Why recovery spend is refused now, or null. */
const spendRefusal = () => {
    const parsed = ledgerParse();
    if (parsed.state === "malformed") {
        return `attempt ledger is malformed: ${parsed.problems.join("; ")}`;
    }
    if (parsed.state === "closed") {
        return "campaign is closed; no judge event or child process is permitted";
    }
    return null;
};

/** Whether an existing recovery attempt carries a usable judgement. */
const usableJudgement = (dir) => {
    const judgement = readJson(join(dir, "judgement.json"));
    if (judgement?.status === "judged") return true;
    const resolution = readJson(join(dir, "resolution.json"));
    return resolution?.status === "judged";
};

const refusal = spendRefusal();
if (refusal !== null) {
    console.error(`BLOCKER: ${refusal}`);
    process.exit(2);
}

const premise = premiseProblems();
if (premise.length > 0) {
    console.error(`BLOCKER: frozen premise changed: ${premise.join("; ")}`);
    process.exit(2);
}

if (loadJudgeKey(ROOT) === null) {
    console.error("BLOCKER: no ZAI_API_KEY");
    process.exit(2);
}

let judged = 0;
for (const slot of slots) {
    const base = join(ROOT, "gen", slot.arm.toLowerCase());
    const caseDir = join(base, "results", slot.stamp, slot.scenario);
    const attemptDir = join(caseDir, "ac", attemptId);
    if (existsSync(attemptDir)) {
        if (usableJudgement(attemptDir)) {
            console.log(`${slot.stamp}: ${attemptId} already judged, preserved`);
            continue;
        }
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            pairId: slot.pairId,
            stamp: slot.stamp,
            arm: slot.arm,
            attemptId,
            reason: "preserved recovery attempt has no usable judgement",
        });
        console.error(
            `BLOCKER: ${slot.stamp} has a preserved ${attemptId} attempt with no usable judgement`,
        );
        process.exit(2);
    }
    const meta = readJson(join(caseDir, "meta.json"));
    if (meta === null || meta.answerValid !== true || meta.exit !== 0) {
        console.error(`${slot.stamp}: trial is not a usable recorded result`);
        process.exit(2);
    }
    const claim = claimBudget(EVIDENCE, "judge", judgeCeiling, {
        stamp: slot.stamp,
        attemptId,
    });
    if (!claim.ok) {
        ledger({
            event: "slot-blocked",
            slot: slot.slot,
            pairId: slot.pairId,
            stamp: slot.stamp,
            arm: slot.arm,
            attemptId,
            reason: claim.reason,
        });
        console.error(`BLOCKER: ${claim.reason}`);
        process.exit(2);
    }
    ledger({
        event: "judge-launch",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        attemptId,
        recovery: true,
    });
    advanceClaim(claim.claim, "spawned");
    const result = spawnSync(
        process.execPath,
        [
            AC,
            "judge",
            "--base", base,
            "--stamp", slot.stamp,
            "--case", slot.scenario,
            "--truth", join(
                ROOT,
                "arms/a/tests/fixtures/placement-harness/prod014/truth.json",
            ),
            "--spec", join(EVIDENCE, "measurement-spec.json"),
            "--attempt", attemptId,
            "--launcher", join(
                MEASUREMENT,
                "tests/fixtures/placement-harness/ac/judge-launcher.sh",
            ),
            "--model", JUDGE,
            "--workdir", join(EVIDENCE, "ac-runs"),
            "--timeout", "600000",
        ],
        { encoding: "utf8", timeout: 720000 },
    );
    advanceClaim(claim.claim, "closed");
    const judgement = readJson(join(attemptDir, "judgement.json"));
    loggerExit(slot, result, judgement);
    if (judgement?.status !== "judged") {
        console.error(
            `BLOCKER: ${slot.stamp} recovery judgement is ${judgement?.status ?? "missing"}`,
        );
        process.exit(2);
    }
    judged += 1;
    console.log(
        `${slot.stamp}: ${judgement.documentationOutcome}; retrieval ${judgement.retrievalApplication?.state ?? "n/a"}`,
    );
}

ledger({ event: "recovery-complete", attempted: slots.length, judged });
console.log(`recovery complete: ${judged} judgement(s)`);

/**
 * Record one recovery judge outcome without ever recording the key.
 * @param slot The scheduled slot.
 * @param result The spawned process result.
 * @param judgement The parsed judgement pointer.
 */
function loggerExit(slot, result, judgement) {
    ledger({
        event: "judge-exit",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        arm: slot.arm,
        scenario: slot.scenario,
        attemptId,
        recovery: true,
        exit: result.status,
        status: judgement?.status ?? "missing",
        outcome: judgement?.documentationOutcome ?? null,
        retrieval: judgement?.retrievalApplication?.state ?? null,
    });
}

files.dry-check.mjs:
// Bounded, no-model dry run for the productivity screen.
//
// 1. Replays the committed mini corpus through the analyser.
// 2. Builds synthetic ac-v1 evidence for this campaign's manifest and checks
//    the analyser consumes the scenario-keyed preservation inventory.
// 3. Runs one ac judge call through a mock launcher against synthetic trial
//    evidence, checking the retrieval-application field and packet contract.
// 4. Runs the four new pristine primary checks against the broken premise and
//    against a corrected copy.
import { spawnSync } from "node:child_process";
import {
    appendFileSync,
    existsSync,
    mkdirSync,
    mkdtempSync,
    readFileSync,
    readdirSync,
    rmSync,
    writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const DRY = join(ROOT, "evidence/dry");
const MEASUREMENT = join(ROOT, "measurement");
const ANALYSER = join(
    MEASUREMENT,
    "tests/fixtures/placement-harness/analysis/analyse.mts",
);
const AC = join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs");
const manifest = join(ROOT, "prepare/manifest.json");
const scenarios = ["R01", "S02", "R02", "R03", "S05", "S06", "S07", "R04"];
const schedule = JSON.parse(
    readFileSync(join(ROOT, "evidence/schedule.json"), "utf8"),
).slots;
const results = {};

const write = (path, contents) => {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, contents, "utf8");
};
const json = (path, value) =>
    write(path, `${JSON.stringify(value, null, 2)}\n`);

/** One synthetic trial directory, valid for the ac-v1 adapter. */
function syntheticTrial(base, slot, overrides = {}) {
    const dir = join(base, "results", slot.stamp, slot.scenario);
    const outcome = overrides.outcome ?? "none";
    const created = outcome === "useful-create";
    const modified = outcome === "useful-update";
    json(join(dir, "meta.json"), {
        exit: 0,
        signal: null,
        answerValid: true,
        policyViolations: [],
    });
    json(join(dir, "gate.json"), {
        status: overrides.gateStatus ?? "pass",
        reason: null,
    });
    json(join(dir, "primary-check.json"), {
        status: overrides.primaryStatus ?? "pass",
        exit: 0,
        stdout: "synthetic primary pass",
        stderr: "",
    });
    write(join(dir, "final.md"), "synthetic answer\n");
    write(
        join(dir, "writes.txt"),
        `${created ? `added lakes/docs/${slot.scenario}.md` : "none"}\n${modified ? "modified lakes/docs/ops/upgrade.md" : "modified work/deploy/staging.json"}\n`,
    );
    write(
        join(dir, "docs-operations.jsonl"),
        `${JSON.stringify({
            status: "completed",
            surface: "native",
            input: overrides.read
                ? { read: overrides.read }
                : { search: "synthetic" },
        })}\n`,
    );
    write(join(dir, "prompt.md"), "synthetic prompt\n");
    write(join(dir, "stdout.jsonl"), "");
    json(join(dir, "ac/attempt-001/meta.json"), {
        stamp: slot.stamp,
        caseId: slot.scenario,
        judgeModel: "zai-coding-plan/glm-5.3-flash",
        status: "finished",
        exit: 0,
        state: {
            documentsChanged: created || modified,
            createdPaths: created ? [`docs/${slot.scenario}.md`] : [],
            modifiedPaths: modified ? ["docs/ops/upgrade.md"] : [],
            removedPaths: [],
        },
    });
    const judgement = {
        status: "judged",
        documentationOutcome: outcome,
        documentationReason: "synthetic dry-run judgement",
        evidence: ["synthetic evidence"],
        uniformity: undefined,
        ...(overrides.preservation === undefined
            ? {}
            : { preservation: overrides.preservation }),
        ...(overrides.retrieval === undefined
            ? {}
            : {
                  retrievalApplication: {
                      state: overrides.retrieval,
                      quote: "synthetic retrieval quote",
                  },
              }),
    };
    delete judgement.uniformity;
    json(join(dir, "ac/attempt-001/judgement.json"), judgement);
    return { dir, created, modified };
}

// 1. Mini corpus replay.
{
    const out = join(DRY, "mini-report");
    rmSync(out, { recursive: true, force: true });
    const run = spawnSync(
        process.execPath,
        [
            ANALYSER,
            "--campaign",
            join(
                MEASUREMENT,
                "tests/fixtures/analysis/manifests/mini.json",
            ),
            "--evidence-root",
            join(MEASUREMENT, "tests/fixtures/analysis/mini-corpus"),
            "--out",
            out,
        ],
        { encoding: "utf8", timeout: 120000 },
    );
    if (run.status !== 0) throw new Error(`mini replay failed: ${run.stderr}`);
    results.miniReplay = {
        status: "pass",
        outputs: readdirSync(out).sort(),
    };
}

// 2. Synthetic campaign replay through the frozen manifest.
{
    const base = join(DRY, "campaign");
    rmSync(base, { recursive: true, force: true });
    write(join(base, "evidence/ATTEMPTS.jsonl"), "");
    write(
        join(base, "evidence/measurement-spec.json"),
        readFileSync(join(ROOT, "evidence/measurement-spec.json"), "utf8"),
    );
    const dryManifest = JSON.parse(
        readFileSync(join(ROOT, "prepare/manifest.json"), "utf8"),
    );
    dryManifest.assessment.attemptId = "attempt-001";
    json(join(DRY, "manifest-dry.json"), dryManifest);
    const r02Preservation = {
        poolSize: { state: "retained", quote: "at most 10 connections" },
        acquireTimeout: { state: "retained", quote: "up to 5 seconds" },
        startupMigrations: { state: "retained", quote: "at application startup" },
        obsoleteTlsClaim: { state: "removed", quote: "(absent)" },
    };
    const s07Preservation = {
        snapshot: { state: "retained", quote: "Take a snapshot" },
        rollback: { state: "retained", quote: "Restore the snapshot" },
        legacyCondition: { state: "removed", quote: "(absent)" },
    };
    for (const slot of schedule) {
        const armDir = join(base, slot.arm === "A" ? "gen/a" : "gen/b");
        const recording = ["R01", "R02", "S05", "S07"].includes(slot.scenario);
        const outcome = recording
            ? slot.scenario === "R01" || slot.scenario === "S05"
                ? "useful-create"
                : "useful-update"
            : "none";
        syntheticTrial(armDir, slot, {
            outcome,
            read: ["S02", "R02", "S06", "S07", "R04"].includes(slot.scenario)
                ? `${slot.scenario === "R02" ? "db/pool.md" : slot.scenario === "R04" ? "db/migrations.md" : "ops/upgrade.md"}`
                : undefined,
            preservation:
                slot.scenario === "R02" && outcome === "useful-update"
                    ? r02Preservation
                    : slot.scenario === "S07" && outcome === "useful-update"
                      ? s07Preservation
                      : undefined,
            retrieval: ["S02", "R02", "S06", "S07", "R04"].includes(
                slot.scenario,
            )
                ? "applied"
                : undefined,
        });
        appendFileSync(
            join(base, "evidence/ATTEMPTS.jsonl"),
            `${JSON.stringify({ at: "2026-11-11T00:00:00Z", event: "launch", stamp: slot.stamp })}\n`,
        );
        appendFileSync(
            join(base, "evidence/ATTEMPTS.jsonl"),
            `${JSON.stringify({ at: "2026-11-11T00:01:00Z", event: "judge-launch", stamp: slot.stamp })}\n`,
        );
    }
    // A missing-evidence copy: remove one judgement to prove unknown bounds.
    const missing = join(DRY, "campaign-missing");
    rmSync(missing, { recursive: true, force: true });
    spawnSync("cp", ["-a", base, missing]);
    rmSync(
        join(missing, "gen/b/results/pd-B-r0-S02/S02/ac"),
        { recursive: true, force: true },
    );
    for (const [label, root] of [
        ["campaign", base],
        ["missing", missing],
    ]) {
        const out = join(DRY, `${label}-report`);
        rmSync(out, { recursive: true, force: true });
        const run = spawnSync(
            process.execPath,
            [
                ANALYSER,
                "--campaign",
                join(DRY, "manifest-dry.json"),
                "--evidence-root",
                root,
                "--out",
                out,
            ],
            { encoding: "utf8", timeout: 120000 },
        );
        if (run.status !== 0)
            throw new Error(`${label} replay failed: ${run.stderr}`);
        const analysis = JSON.parse(
            readFileSync(join(out, "analysis.json"), "utf8"),
        );
        results[`replay-${label}`] = {
            status: "pass",
            decision: analysis.decision?.overall ?? "unknown",
            outputs: readdirSync(out).sort(),
            unmatched: analysis.pairing?.unmatched?.length ?? null,
        };
    }
    const missingAnalysis = JSON.parse(
        readFileSync(join(DRY, "missing-report/analysis.json"), "utf8"),
    );
    results.missingEvidence = {
        status: "pass",
        decision: missingAnalysis.decision?.overall ?? "unknown",
        unmatched: missingAnalysis.pairing?.unmatched?.length ?? null,
    };
}

// 3. One mocked judge call through the real ac contract.
{
    const base = join(DRY, "judge");
    rmSync(base, { recursive: true, force: true });
    const caseId = "S07";
    const stamp = "pd-B-r0-S07";
    const caseDir = join(base, "results", stamp, caseId);
    write(join(base, "fixtures", caseId, "work/AGENTS.md"), "PERMISSION\n");
    write(
        join(base, "fixtures", caseId, "lakes/docs/ops/upgrade.md"),
        "# Upgrade\n\n- Take a snapshot.\n- Restore the snapshot to roll back.\n- Upgrades from any version below 4.2 must run migrate:legacy.\n",
    );
    json(join(caseDir, "meta.json"), {
        exit: 0,
        signal: null,
        answerValid: true,
        policyViolations: [],
    });
    write(join(caseDir, "prompt.md"), "Fix the upgrade check.\n");
    write(
        join(caseDir, "live/lakes/docs/ops/upgrade.md"),
        "# Upgrade\n\n- Take a snapshot.\n- Restore the snapshot to roll back.\n- Only 3.x upgrades run migrate:legacy.\n",
    );
    write(join(caseDir, "writes.txt"), "modified lakes/docs/ops/upgrade.md\n");
    json(join(caseDir, "primary-check.json"), {
        status: "pass",
        exit: 0,
        stdout: "",
        stderr: "",
    });
    write(
        join(caseDir, "docs-operations.jsonl"),
        `${JSON.stringify({
            status: "completed",
            surface: "native",
            input: { read: "ops/upgrade.md" },
        })}\n`,
    );
    write(join(caseDir, "final.md"), "Corrected the note.\n");
    write(
        join(base, "truth.json"),
        `${JSON.stringify({ S07: "The below-4.2 condition is obsolete." })}\n`,
    );
    const answer = JSON.stringify({
        documentationOutcome: "useful-update",
        documentationReason: "corrected the obsolete condition",
        evidence: ["Only 3.x upgrades run migrate:legacy."],
        preservation: {
            snapshot: { state: "retained", quote: "Take a snapshot." },
            rollback: { state: "retained", quote: "Restore the snapshot." },
            legacyCondition: { state: "removed", quote: "(absent)" },
        },
        retrievalApplication: {
            state: "applied",
            quote: "Only 3.x upgrades run migrate:legacy.",
        },
    });
    const launcher = join(DRY, "mock-judge.sh");
    write(
        launcher,
        `#!/usr/bin/env sh\nprintf '%s\\n' '${JSON.stringify({ type: "text", part: { type: "text", text: answer } })}'\n`,
    );
    spawnSync("chmod", ["+x", launcher]);
    const run = spawnSync(
        process.execPath,
        [
            AC,
            "judge",
            "--base", base,
            "--stamp", stamp,
            "--case", caseId,
            "--truth", join(base, "truth.json"),
            "--spec", join(ROOT, "evidence/measurement-spec.json"),
            "--launcher", launcher,
            "--model", "zai-coding-plan/glm-5.3-flash",
            "--workdir", join(DRY, "judge-runs"),
        ],
        { encoding: "utf8", timeout: 120000 },
    );
    const judgement = JSON.parse(
        readFileSync(join(caseDir, "ac/attempt-001/judgement.json"), "utf8"),
    );
    if (run.status !== 0 || judgement.status !== "judged") {
        throw new Error(`mock judge failed: ${run.stderr}`);
    }
    results.mockJudge = {
        status: "pass",
        outcome: judgement.documentationOutcome,
        retrieval: judgement.retrievalApplication?.state,
        preservation: Object.keys(judgement.preservation ?? {}),
    };
}

// 4. Broken premise and corrected fix for the four new primary checks.
{
    const fixtures = join(ROOT, "gen/a/fixtures");
    const checks = join(
        ROOT,
        "arms/a/tests/fixtures/placement-harness/primary-checks",
    );
    const temp = mkdtempSync(join(tmpdir(), "pd-dry-"));
    try {
        const expected = [];
        for (const id of ["S02", "S05", "S06", "S07"]) {
            const live = join(temp, id);
            spawnSync("cp", ["-a", join(fixtures, id, "work"), live]);
            const broken = spawnSync(
                process.execPath,
                [join(checks, `${id}.mjs`), live, join(fixtures, id, "work")],
                { encoding: "utf8", timeout: 120000 },
            );
            expected.push({ id, brokenExit: broken.status });
        }
        results.brokenPremises = expected;
    } finally {
        rmSync(temp, { recursive: true, force: true });
    }
}

